"""
Swarm V2 Self-Healing Infrastructure
Phase 5: Flow (DevOps Engineer)

Automatically monitors and restarts the Swarm OS API and Dashboard
if connectivity heartbeats fail for more than 60 seconds.

This provides infrastructure-level self-healing independent of agent-level recovery.
Race-condition-free implementation with proper synchronization primitives.
"""

import asyncio
import subprocess
import time
import logging
import os
import signal
import psutil
import urllib.request
import urllib.error
from typing import Dict, List, Optional, Any, Callable, Awaitable
from asyncio import Lock, Semaphore
from datetime import datetime, timezone
from enum import Enum
from pydantic import BaseModel, Field, field_validator


class ServiceStatus(str, Enum):
    """Service health status enum for backward compatibility."""
    HEALTHY = "healthy"
    DEGRADED = "degraded"
    UNRESPONSIVE = "unresponsive"
    RESTARTING = "restarting"
    STOPPED = "stopped"


class ServiceConfig(BaseModel):
    """Configuration for a monitored service (Pydantic v2)."""
    name: str = Field(..., min_length=1, pattern=r'^[a-zA-Z_][a-zA-Z0-9_]*$')
    health_endpoint: str = Field(..., min_length=1)
    restart_command: List[str] = Field(..., min_length=1)
    port: int = Field(..., ge=1, le=65535)
    heartbeat_timeout: int = Field(default=60, ge=1)
    restart_cooldown: int = Field(default=30, ge=1)
    max_restart_attempts: int = Field(default=3, ge=1)


class ServiceHealthRecord(BaseModel):
    """Immutable health status record for a monitored service."""
    service_name: str = Field(..., min_length=1, pattern=r'^[a-zA-Z_][a-zA-Z0-9_]*$')
    status: ServiceStatus = Field(default=ServiceStatus.HEALTHY)
    last_heartbeat: datetime = Field(default_factory=lambda: datetime.now(timezone.utc))
    last_response_time: float = Field(default=0.0, ge=0.0)
    consecutive_failures: int = Field(default=0, ge=0)
    restart_count: int = Field(default=0, ge=0)
    last_restart: Optional[datetime] = None
    error_message: str = Field(default="", max_length=1000)
    pid: Optional[int] = Field(default=None, ge=0)

    @field_validator('last_response_time')
    @classmethod
    def validate_response_time(cls, v: float) -> float:
        """Ensure response time is reasonable (max 30 seconds)."""
        if v > 30.0:
            raise ValueError(f"Response time {v}s exceeds maximum 30s")
        return v


class RestartOperation(BaseModel):
    """Atomic restart operation record for auditing."""
    service_name: str
    timestamp: datetime = Field(default_factory=lambda: datetime.now(timezone.utc))
    attempt_number: int = Field(..., ge=1)
    success: bool = False
    error_message: str = Field(default="", max_length=1000)
    duration_seconds: float = Field(default=0.0, ge=0.0)


class SelfHealingInfra:
    """
    Thread-safe self-healing infrastructure with proper synchronization.
    
    Monitors API and Dashboard services, automatically restarting them
    if heartbeat checks fail for more than the configured timeout.
    Implements per-service locks and global semaphore to prevent race conditions.
    """
    
    def __init__(self, check_interval: int = 10, max_concurrent_restarts: int = 2):
        self.check_interval = check_interval
        self.running = False
        self._services: Dict[str, ServiceConfig] = {}
        self._health_status: Dict[str, ServiceHealthRecord] = {}
        self._restart_history: List[RestartOperation] = []
        
        # Synchronization primitives
        self._state_lock = Lock()
        self._restart_semaphore = Semaphore(max_concurrent_restarts)
        self._service_locks: Dict[str, Lock] = {}
        
        # Configure structured logging
        self.logger = logging.getLogger("SelfHealingInfra")
        self._setup_logging()
        
        # Default services to monitor
        self._register_default_services()
    
    def _setup_logging(self):
        """Configure structured logging with correlation IDs."""
        if not self.logger.handlers:
            handler = logging.StreamHandler()
            handler.setFormatter(logging.Formatter(
                "%(asctime)s [%(levelname)s] [correlation_id=%(correlation_id)s] [SelfHealing] %(message)s"
            ))
            self.logger.addHandler(handler)
            self.logger.setLevel(logging.INFO)
    
    def _register_default_services(self):
        """Register the default Swarm OS services."""
        # Swarm API
        self.register_service(ServiceConfig(
            name="swarm_api",
            health_endpoint="http://localhost:8021/health",
            restart_command=["python", "-m", "uvicorn", "swarm_v2.app_v2:app", "--host", "0.0.0.0", "--port", "8021"],
            port=8021,
            heartbeat_timeout=300,
            restart_cooldown=30,
            max_restart_attempts=3
        ))
        
        # Dashboard (Vite dev server)
        self.register_service(ServiceConfig(
            name="swarm_dashboard",
            health_endpoint="http://localhost:5173/",
            restart_command=["npm", "run", "dev"],
            port=5173,
            heartbeat_timeout=60,
            restart_cooldown=30,
            max_restart_attempts=3,
        ))
        
        # Dashboard v2 (if running)
        self.register_service(ServiceConfig(
            name="swarm_dashboard_v2",
            health_endpoint="http://localhost:5174/",
            restart_command=["npm", "run", "dev", "--", "--port", "5174"],
            port=5174,
            heartbeat_timeout=60,
            restart_cooldown=30,
            max_restart_attempts=3,
        ))
    
    def register_service(self, config: ServiceConfig) -> None:
        """
        Register a service to monitor.
        
        Args:
            config: ServiceConfig instance with service details
        """
        self._services[config.name] = config
        self._health_status[config.name] = ServiceHealthRecord(
            service_name=config.name,
            status=ServiceStatus.HEALTHY
        )
    
    async def _get_service_lock(self, service_name: str) -> Lock:
        """Get or create a per-service lock."""
        async with self._state_lock:
            if service_name not in self._service_locks:
                self._service_locks[service_name] = Lock()
            return self._service_locks[service_name]
    
    async def _safe_update_health(
        self, 
        service_name: str, 
        update_fn: Callable[[ServiceHealthRecord], Awaitable[ServiceHealthRecord]]
    ) -> ServiceHealthRecord:
        """
        Atomically update health status for a service.
        
        Args:
            service_name: Name of the service
            update_fn: Async callable that receives current record and returns updated record
            
        Returns:
            Updated ServiceHealthRecord
        """
        async with self._state_lock:
            current = self._health_status.get(service_name)
            if current is None:
                current = ServiceHealthRecord(service_name=service_name)
            updated = await update_fn(current)
            self._health_status[service_name] = updated
            return updated
    
    async def _safe_restart_service(self, service_name: str) -> bool:
        """
        Thread-safe service restart with cooldown enforcement.
        
        Args:
            service_name: Name of service to restart
            
        Returns:
            bool: True if restart was initiated successfully
        """
        service_lock = await self._get_service_lock(service_name)
        
        async with service_lock:
            # Check cooldown
            async with self._state_lock:
                current_health = self._health_status.get(service_name)
                if current_health and current_health.last_restart:
                    cooldown_seconds = self._services[service_name].restart_cooldown
                    elapsed = (datetime.now(timezone.utc) - current_health.last_restart).total_seconds()
                    if elapsed < cooldown_seconds:
                        self.logger.warning(
                            f"Restart cooldown active for {service_name}: "
                            f"{elapsed:.1f}s elapsed, {cooldown_seconds}s required",
                            extra={'correlation_id': service_name}
                        )
                        return False
            
            # Acquire semaphore slot
            async with self._restart_semaphore:
                start_time = datetime.now(timezone.utc)
                attempt_number = current_health.restart_count + 1 if current_health else 1
                
                try:
                    # Update status to restarting
                    await self._safe_update_health(service_name, lambda r: r.model_copy(
                        update={'status': ServiceStatus.RESTARTING, 'restart_count': attempt_number}
                    ))
                    
                    # Execute restart
                    config = self._services[service_name]
                    process = await asyncio.create_subprocess_exec(
                        *config.restart_command,
                        stdout=asyncio.subprocess.PIPE,
                        stderr=asyncio.subprocess.PIPE
                    )
                    
                    # Wait briefly for process start
                    try:
                        await asyncio.wait_for(process.wait(), timeout=5.0)
                    except asyncio.TimeoutError:
                        pass  # Process is still running, which is expected
                    
                    duration = (datetime.now(timezone.utc) - start_time).total_seconds()
                    
                    # Record successful restart
                    restart_op = RestartOperation(
                        service_name=service_name,
                        attempt_number=attempt_number,
                        success=True,
                        duration_seconds=duration
                    )
                    
                    async with self._state_lock:
                        self._restart_history.append(restart_op)
                        # Trim history to prevent memory leak
                        if len(self._restart_history) > 1000:
                            self._restart_history = self._restart_history[-1000:]
                    
                    self.logger.info(
                        f"Successfully restarted {service_name} "
                        f"(attempt {attempt_number}, duration: {duration:.2f}s)",
                        extra={'correlation_id': service_name}
                    )
                    
                    return True
                    
                except Exception as e:
                    duration = (datetime.now(timezone.utc) - start_time).total_seconds()
                    
                    # Record failed restart
                    restart_op = RestartOperation(
                        service_name=service_name,
                        attempt_number=attempt_number,
                        success=False,
                        error_message=str(e),
                        duration_seconds=duration
                    )
                    
                    async with self._state_lock:
                        self._restart_history.append(restart_op)
                    
                    self.logger.error(
                        f"Failed to restart {service_name}: {e}",
                        extra={'correlation_id': service_name}
                    )
                    
                    # Restore previous status
                    await self._safe_update_health(service_name, lambda r: r.model_copy(
                        update={'status': ServiceStatus.UNRESPONSIVE, 'error_message': str(e)}
                    ))
                    
                    return False
    
    async def _check_service_health(self, service_name: str) -> None:
        """
        Thread-safe health check with proper state management.
        
        Args:
            service_name: Name of service to check
        """
        config = self._services[service_name]
        start_time = time.time()
        
        try:
            # Perform health check
            response = await asyncio.get_event_loop().run_in_executor(
                None, 
                lambda: urllib.request.urlopen(
                    config.health_endpoint, 
                    timeout=5
                )
            )
            
            response_time = time.time() - start_time
            
            # Update health status atomically
            await self._safe_update_health(service_name, lambda r: r.model_copy(
                update={
                    'status': ServiceStatus.HEALTHY,
                    'last_heartbeat': datetime.now(timezone.utc),
                    'last_response_time': response_time,
                    'consecutive_failures': 0,
                    'error_message': ''
                }
            ))
            
        except Exception as e:
            response_time = time.time() - start_time
            
            # Update failure count atomically
            await self._safe_update_health(service_name, lambda r: r.model_copy(
                update={
                    'status': ServiceStatus.UNRESPONSIVE if r.consecutive_failures >= 2 else ServiceStatus.DEGRADED,
                    'last_heartbeat': datetime.now(timezone.utc),
                    'last_response_time': response_time,
                    'consecutive_failures': r.consecutive_failures + 1,
                    'error_message': str(e)
                }
            ))
            
            # Check if restart is needed
            async with self._state_lock:
                current = self._health_status[service_name]
                if (current.consecutive_failures * self.check_interval >= 
                    config.heartbeat_timeout):
                    # Initiate restart asynchronously
                    asyncio.create_task(self._safe_restart_service(service_name))
    
    async def start_monitoring(self) -> None:
        """
        Start the health monitoring loop.
        
        Continuously checks all registered services and triggers restarts
        when heartbeat timeouts are exceeded.
        """
        self.running = True
        self.logger.info(
            "Self-healing monitoring started",
            extra={'correlation_id': 'system'}
        )
        
        while self.running:
            for service_name in list(self._services.keys()):
                await self._check_service_health(service_name)
            await asyncio.sleep(self.check_interval)
    
    async def stop_monitoring(self) -> None:
        """Gracefully stop the health monitoring loop."""
        self.running = False
        self.logger.info(
            "Self-healing monitoring stopped",
            extra={'correlation_id': 'system'}
        )
    
    def get_health_status(self, service_name: Optional[str] = None) -> Dict[str, Any]:
        """
        Get current health status for services.
        
        Args:
            service_name: Optional specific service name
            
        Returns:
            Dict with service health information
        """
        if service_name:
            record = self._health_status.get(service_name)
            if record:
                return record.model_dump()
            return {}
        return {name: record.model_dump() for name, record in self._health_status.items()}
    
    def get_restart_history(self, limit: int = 100) -> List[Dict[str, Any]]:
        """
        Get restart operation history.
        
        Args:
            limit: Maximum number of records to return
            
        Returns:
            List of restart operation dictionaries
        """
        return [op.model_dump() for op in self._restart_history[-limit:]]